const root='/home/ubuntu/dev/explorakit',req=require('node:module').createRequire(root+'/package.json'),{chromium}=req('playwright'),fs=req('node:fs'),assert=req('node:assert/strict');
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});try{const page=await browser.newPage({viewport:{width:896,height:640}});await page.setContent('<style>html,body{margin:0;background:#080812}canvas{display:block;image-rendering:pixelated}</style><canvas width="896" height="640"></canvas>');const source=fs.readFileSync(root+'/vue-explorakit/src/services/mirrorRiftRenderer.js').toString('base64'),art=fs.readFileSync(root+'/vue-explorakit/src/assets/route2_maison.png').toString('base64');await page.evaluate(async({source,art})=>{window.m=await import('data:text/javascript;base64,'+source);window.image=new Image();image.src='data:image/png;base64,'+art;await image.decode();window.c=document.querySelector('canvas').getContext('2d');window.state={ruined:true,stage:'open',rift:{x:13,y:10},clone:{x:13,y:13}};window.paint=(time,scene,motion=true)=>{c.clearRect(0,0,896,640);c.drawImage(image,0,0,896,640);m.drawMirrorGround(c,'route2_maison',state,scene,time,motion);};},{source,art});const out='/tmp/riftmon-mirror-polish-canvas';fs.mkdirSync(out,{recursive:true});for(const ms of [800,2600,4800,7400]){await page.evaluate(ms=>paint(ms,{map:'route2_maison',phase:'opening',startedAt:0,duration:8000}),ms);await page.screenshot({path:out+'/opening-'+ms+'.png'});}await page.evaluate(()=>paint(16000,null));await page.screenshot({path:out+'/open.png'});await page.evaluate(()=>paint(16000,null,false));await page.screenshot({path:out+'/reduced.png'});
const result=await page.evaluate(()=>{let start=performance.now();for(let i=0;i<120;i++)paint(20000+i*34,null);const average=(performance.now()-start)/120;paint(30000,null);const moving=c.getImageData(0,0,896,640).data;paint(31000,null);const later=c.getImageData(0,0,896,640).data;let changed=0;for(let i=0;i<moving.length;i++)if(moving[i]!==later[i])changed++;paint(32000,null,false);const reduced=c.getImageData(0,0,896,640).data;paint(40000,null,false);const still=c.getImageData(0,0,896,640).data;let reducedChanges=0;for(let i=0;i<still.length;i++)if(still[i]!==reduced[i])reducedChanges++;m.releaseMirrorEffects();paint(40000,null);return{averageWorldAndEffectMs:average,animatedChannelsChanged:changed,reducedChannelsChanged:reducedChanges,releaseAndRecreate:true};});assert(result.animatedChannelsChanged>100);assert.equal(result.reducedChannelsChanged,0);fs.writeFileSync(out+'/results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
